const order = input['iterateShopifyOrders'][0];

const orderName = order.name || String(order.number || order.orderNumber || '');
const orderId = String(order.id || '');

return {
  shopifyOrderId: orderId,
  shopifyOrderName: orderName,
  netsuiteShopifyOrderValue: orderName,
  salesOrderMemo: `Shopify Order ${orderName}`
};

const orderInfo = ${JSON.stringify(input?.mapShopifyOrderIdentifiers?.[0])};

function execute() {
  try {
    const shopifyOrderValue = String(orderInfo?.netsuiteShopifyOrderValue || '').trim();

    if (!shopifyOrderValue) {
      return [];
    }

    const salesOrderSearch = search.create({
      type: search.Type.SALES_ORDER,
      filters: [
        ['mainline', 'is', 'T'],
        'AND',
        ['custbody_shopify_ord_id', 'is', shopifyOrderValue]
      ],
      columns: [
        search.createColumn({ name: 'internalid' }),
        search.createColumn({ name: 'tranid' }),
        search.createColumn({ name: 'entity' }),
        search.createColumn({ name: 'memo' }),
        search.createColumn({ name: 'custbody_shopify_ord_id' })
      ]
    });

    const matches = [];

    salesOrderSearch.run().each(function (result) {
      const salesOrderId = result.getValue({ name: 'internalid' });
      const salesOrderRec = record.load({
        type: record.Type.SALES_ORDER,
        id: salesOrderId,
        isDynamic: false
      });

      const itemLines = {};
      const lineCount = salesOrderRec.getLineCount({ sublistId: 'item' });

      for (let line = 0; line < lineCount; line++) {
        const lineKey = `line${line + 1}`;
        itemLines[lineKey] = {
          item: salesOrderRec.getSublistValue({ sublistId: 'item', fieldId: 'item', line: line }),
          itemDisplay: salesOrderRec.getSublistText({ sublistId: 'item', fieldId: 'item', line: line }),
          quantity: salesOrderRec.getSublistValue({ sublistId: 'item', fieldId: 'quantity', line: line }),
          rate: salesOrderRec.getSublistValue({ sublistId: 'item', fieldId: 'rate', line: line }),
          amount: salesOrderRec.getSublistValue({ sublistId: 'item', fieldId: 'amount', line: line })
        };
      }

      matches.push({
        id: String(salesOrderId),
        type: 'salesord',
        fields: {
          id: String(salesOrderId),
          tranid: result.getValue({ name: 'tranid' }),
          entity: result.getValue({ name: 'entity' }),
          memo: result.getValue({ name: 'memo' }),
          custbody_shopify_ord_id: result.getValue({ name: 'custbody_shopify_ord_id' })
        },
        sublists: {
          item: itemLines
        }
      });

      return false;
    });

    return matches;

  } catch (error) {
    return {
      success: false,
      message: error.message,
      stack: error.stack,
      error: error
    };
  }
}

