const orderInfo = input['mapShopifyOrderIdentifiers'][0];
const refunds = input['shopifyGetRefundsByOrderId'] || [];

return refunds
  .map(refund => {
    const refundId = String(refund.id || '');
    const items = (refund.refundLineItems || [])
      .filter(line => Number(line.quantity || 0) > 0)
      .map(line => ({
        lineItemId: String(line.lineItemId || line.lineItem?.id || ''),
        sku: String(line.lineItem?.sku || '').trim().toUpperCase(),
        name: line.lineItem?.name || '',
        quantity: Number(line.quantity || 0),
        subtotal: Number(line.subtotal || 0)
      }))
      .filter(line => line.sku && line.quantity > 0);

    return {
      refundId,
      shopifyOrderId: orderInfo.shopifyOrderId,
      shopifyOrderName: orderInfo.shopifyOrderName,
      externalId: `lionel-shopify-rma-${orderInfo.shopifyOrderId}-${refundId}`,
      items
    };
  })
  .filter(refund => refund.refundId && refund.items.length > 0);

const refundRequest = ${JSON.stringify(input?.iterateRefundRequests?.[0])};

function execute() {
  try {
    const externalId = String(refundRequest?.externalId || '').trim();

    if (!externalId) {
      return [];
    }

    const rmaSearch = search.create({
      type: search.Type.RETURN_AUTHORIZATION,
      filters: [
        ['mainline', 'is', 'T'],
        'AND',
        ['externalidstring', 'is', externalId]
      ],
      columns: [
        search.createColumn({ name: 'internalid' }),
        search.createColumn({ name: 'tranid' }),
        search.createColumn({ name: 'externalid' }),
        search.createColumn({ name: 'createdfrom' }),
        search.createColumn({ name: 'statusref' })
      ]
    });

    const matches = [];

    rmaSearch.run().each(function (result) {
      matches.push({
        id: String(result.getValue({ name: 'internalid' })),
        type: 'rtnauth',
        fields: {
          id: String(result.getValue({ name: 'internalid' })),
          tranid: result.getValue({ name: 'tranid' }),
          externalid: result.getValue({ name: 'externalid' }),
          createdfrom: result.getValue({ name: 'createdfrom' }),
          status: result.getValue({ name: 'statusref' })
        }
      });

      return false;
    });

    return matches;

  } catch (error) {
    return {
      success: false,
      message: error.message,
      stack: error.stack,
      error: error
    };
  }
}

