const salesOrder = input['netsuiteFindMatchingSalesOrder'][0];
const refund = input['iterateRefundRequests'][0];
const nsLines = Object.values(salesOrder?.sublists?.item || {});

const matched = [];
const missing = [];

for (const refundItem of refund.items) {
  const nsLine = nsLines.find(line => String(line.itemDisplay || '').trim().toUpperCase() === refundItem.sku);

  if (!nsLine) {
    missing.push(refundItem);
    continue;
  }

  matched.push({
    sku: refundItem.sku,
    itemName: refundItem.name,
    netsuiteItemId: nsLine.item,
    quantity: refundItem.quantity,
    subtotal: refundItem.subtotal
  });
}

return {
  refundId: refund.refundId,
  externalId: refund.externalId,
  shopifyOrderId: refund.shopifyOrderId,
  shopifyOrderName: refund.shopifyOrderName,
  matched,
  missing,
  hasMatchedItems: matched.length > 0
};

const salesOrder = ${JSON.stringify(input?.netsuiteFindMatchingSalesOrder?.[0])};
const rmaData = ${JSON.stringify(input?.mapMatchRefundedItemsToSalesOrderLines?.[0])};

function safeGetSublistValue(rec, sublistId, fieldId, line) {
  try {
    return rec.getSublistValue({
      sublistId: sublistId,
      fieldId: fieldId,
      line: line
    });
  } catch (e) {
    return 'ERROR: ' + e.message;
  }
}

function safeGetSublistText(rec, sublistId, fieldId, line) {
  try {
    return rec.getSublistText({
      sublistId: sublistId,
      fieldId: fieldId,
      line: line
    });
  } catch (e) {
    return 'ERROR: ' + e.message;
  }
}

function getItemKey(itemId) {
  const itemIdNumber = Number(itemId);

  if (isNaN(itemIdNumber)) {
    return null;
  }

  return String(itemIdNumber);
}

function collectItemLines(rec) {
  const lines = [];
  const count = rec.getLineCount({
    sublistId: 'item'
  });

  for (let i = 0; i < count; i++) {
    lines.push({
      line: i,
      itemId: safeGetSublistValue(rec, 'item', 'item', i),
      itemText: safeGetSublistText(rec, 'item', 'item', i),
      lineUniqueKey: safeGetSublistValue(rec, 'item', 'lineuniquekey', i),
      quantity: safeGetSublistValue(rec, 'item', 'quantity', i),
      quantityFulfilled: safeGetSublistValue(rec, 'item', 'quantityfulfilled', i),
      quantityBilled: safeGetSublistValue(rec, 'item', 'quantitybilled', i),
      quantityReturned: safeGetSublistValue(rec, 'item', 'quantityreturned', i),
      quantityRemaining: safeGetSublistValue(rec, 'item', 'quantityremaining', i),
      isClosed: safeGetSublistValue(rec, 'item', 'isclosed', i),
      itemType: safeGetSublistValue(rec, 'item', 'itemtype', i),
      description: safeGetSublistValue(rec, 'item', 'description', i),
      rate: safeGetSublistValue(rec, 'item', 'rate', i),
      amount: safeGetSublistValue(rec, 'item', 'amount', i)
    });
  }

  return lines;
}

function normalizeMatchedItems(matchedItems) {
  return matchedItems.map(function (item) {
    return {
      netsuiteItemId: item.netsuiteItemId,
      netsuiteItemIdNumber: Number(item.netsuiteItemId),
      quantity: item.quantity,
      quantityNumber: Number(item.quantity),
      sku: item.sku,
      title: item.title,
      lineUniqueKey:
        item.lineUniqueKey ||
        item.lineuniquekey ||
        item.netsuiteLineUniqueKey
    };
  });
}

function buildMatchedQuantityBuckets(matchedItems) {
  const buckets = {};
  const invalidMatchedItems = [];

  matchedItems.forEach(function (item) {
    const itemKey = getItemKey(item.netsuiteItemId);
    const quantity = Number(item.quantity);

    if (!itemKey || isNaN(quantity) || quantity <= 0) {
      invalidMatchedItems.push({
        netsuiteItemId: item.netsuiteItemId,
        quantity: item.quantity,
        sku: item.sku,
        title: item.title,
        reason: 'Invalid netsuiteItemId or quantity'
      });
      return;
    }

    if (!buckets[itemKey]) {
      buckets[itemKey] = {
        itemKey: itemKey,
        netsuiteItemIdNumber: Number(item.netsuiteItemId),
        totalQuantity: 0,
        remainingQuantity: 0,
        matches: []
      };
    }

    buckets[itemKey].totalQuantity += quantity;
    buckets[itemKey].remainingQuantity += quantity;
    buckets[itemKey].matches.push({
      netsuiteItemId: item.netsuiteItemId,
      quantity: item.quantity,
      quantityNumber: quantity,
      sku: item.sku,
      title: item.title
    });
  });

  return {
    buckets: buckets,
    invalidMatchedItems: invalidMatchedItems
  };
}

function buildAllocationPlan(returnAuthLines, buckets) {
  const allocationPlan = [];

  returnAuthLines.forEach(function (line) {
    const itemKey = getItemKey(line.itemId);
    const bucket = itemKey ? buckets[itemKey] : null;
    const lineQuantity = Number(line.quantity);
    const maxLineQuantity = !isNaN(lineQuantity) && lineQuantity > 0 ? lineQuantity : 0;
    const remainingBefore = bucket ? bucket.remainingQuantity : 0;
    const allocatedQuantity = bucket
      ? Math.min(bucket.remainingQuantity, maxLineQuantity)
      : 0;

    if (bucket) {
      bucket.remainingQuantity -= allocatedQuantity;
    }

    allocationPlan.push({
      line: line.line,
      itemKey: itemKey,
      itemId: line.itemId,
      itemText: line.itemText,
      lineUniqueKey: line.lineUniqueKey,
      originalQuantity: line.quantity,
      originalQuantityNumber: lineQuantity,
      maxLineQuantity: maxLineQuantity,
      matchedTotalQuantity: bucket ? bucket.totalQuantity : 0,
      matchedRemainingBeforeAllocation: remainingBefore,
      allocatedQuantity: allocatedQuantity,
      matchedRemainingAfterAllocation: bucket ? bucket.remainingQuantity : 0,
      foundMatch: !!bucket,
      action: allocatedQuantity > 0 ? 'keep' : 'remove',
      reason: bucket
        ? allocatedQuantity > 0
          ? 'Allocated refunded quantity to this return authorization line'
          : 'Matched item refund quantity was already fully allocated to earlier lines'
        : 'No matching netsuiteItemId found in rmaData.matched'
    });
  });

  return allocationPlan;
}

function getUnallocatedMatchedQuantities(buckets) {
  return Object.keys(buckets)
    .map(function (itemKey) {
      const bucket = buckets[itemKey];
      return {
        itemKey: itemKey,
        netsuiteItemIdNumber: bucket.netsuiteItemIdNumber,
        totalQuantity: bucket.totalQuantity,
        remainingQuantity: bucket.remainingQuantity,
        matches: bucket.matches
      };
    })
    .filter(function (bucket) {
      return bucket.remainingQuantity > 0;
    });
}

function execute() {
  const debugInfo = {
    salesOrderId: salesOrder && salesOrder.id,
    rmaExternalId: rmaData && rmaData.externalId,
    shopifyOrderName: rmaData && rmaData.shopifyOrderName,

    matchedItemsRaw: rmaData && rmaData.matched,
    matchedItemsNormalized: [],
    matchedQuantityBuckets: [],
    invalidMatchedItems: [],
    unallocatedMatchedQuantities: [],

    salesOrderLineCount: null,
    salesOrderLines: [],

    returnAuthLineCountImmediatelyAfterTransform: null,
    returnAuthLinesImmediatelyAfterTransform: [],

    allocationPlan: [],
    inspectedReturnAuthLines: [],
    keptLines: [],
    removedLines: []
  };

  try {
    const matchedItems = (rmaData && rmaData.matched) || [];
    debugInfo.matchedItemsNormalized = normalizeMatchedItems(matchedItems);

    const salesOrderRec = record.load({
      type: record.Type.SALES_ORDER,
      id: Number(salesOrder.id),
      isDynamic: false
    });

    debugInfo.salesOrderLineCount = salesOrderRec.getLineCount({
      sublistId: 'item'
    });

    debugInfo.salesOrderLines = collectItemLines(salesOrderRec);

    const returnAuthRec = record.transform({
      fromType: record.Type.SALES_ORDER,
      fromId: Number(salesOrder.id),
      toType: record.Type.RETURN_AUTHORIZATION,
      isDynamic: true
    });

    debugInfo.returnAuthLineCountImmediatelyAfterTransform =
      returnAuthRec.getLineCount({
        sublistId: 'item'
      });

    debugInfo.returnAuthLinesImmediatelyAfterTransform =
      collectItemLines(returnAuthRec);

    const matchedQuantityData = buildMatchedQuantityBuckets(matchedItems);
    const matchedQuantityBuckets = matchedQuantityData.buckets;

    debugInfo.invalidMatchedItems = matchedQuantityData.invalidMatchedItems;

    debugInfo.allocationPlan = buildAllocationPlan(
      debugInfo.returnAuthLinesImmediatelyAfterTransform,
      matchedQuantityBuckets
    );

    debugInfo.matchedQuantityBuckets = Object.keys(matchedQuantityBuckets).map(
      function (itemKey) {
        const bucket = matchedQuantityBuckets[itemKey];
        return {
          itemKey: itemKey,
          netsuiteItemIdNumber: bucket.netsuiteItemIdNumber,
          totalQuantity: bucket.totalQuantity,
          remainingQuantityAfterAllocationPlan: bucket.remainingQuantity,
          matches: bucket.matches
        };
      }
    );

    debugInfo.unallocatedMatchedQuantities =
      getUnallocatedMatchedQuantities(matchedQuantityBuckets);

    returnAuthRec.setValue({
      fieldId: 'externalid',
      value: rmaData.externalId
    });

    returnAuthRec.setValue({
      fieldId: 'custbody_shopify_ord_id',
      value: rmaData.shopifyOrderName
    });

    returnAuthRec.setValue({
      fieldId: 'memo',
      value: 'Shopify Order ' + rmaData.shopifyOrderName
    });

    returnAuthRec.setValue({
      fieldId: 'otherrefnum',
      value: rmaData.shopifyOrderName
    });

    returnAuthRec.setValue({
      fieldId: 'custbody_credit_reason_code',
      value: 25
    });

    let hasValidLine = false;

    const allocationByLine = {};
    debugInfo.allocationPlan.forEach(function (allocation) {
      allocationByLine[String(allocation.line)] = allocation;
    });

    const lineCount = returnAuthRec.getLineCount({
      sublistId: 'item'
    });

    for (let i = lineCount - 1; i >= 0; i--) {
      const allocation = allocationByLine[String(i)] || {
        line: i,
        allocatedQuantity: 0,
        action: 'remove',
        reason: 'No allocation plan found for this return authorization line'
      };

      const itemId = returnAuthRec.getSublistValue({
        sublistId: 'item',
        fieldId: 'item',
        line: i
      });

      const lineDebug = {
        line: i,
        returnAuthItemId: itemId,
        returnAuthItemIdNumber: Number(itemId),
        returnAuthItemText: safeGetSublistText(returnAuthRec, 'item', 'item', i),
        returnAuthLineUniqueKey: safeGetSublistValue(
          returnAuthRec,
          'item',
          'lineuniquekey',
          i
        ),
        returnAuthOriginalQuantity: safeGetSublistValue(
          returnAuthRec,
          'item',
          'quantity',
          i
        ),
        foundMatch: allocation.foundMatch || false,
        matchedTotalQuantity: allocation.matchedTotalQuantity || 0,
        matchedRemainingBeforeAllocation:
          allocation.matchedRemainingBeforeAllocation || 0,
        allocatedQuantity: allocation.allocatedQuantity || 0,
        matchedRemainingAfterAllocation:
          allocation.matchedRemainingAfterAllocation || 0,
        action: allocation.action,
        reason: allocation.reason
      };

      debugInfo.inspectedReturnAuthLines.push(lineDebug);

      if (!allocation.allocatedQuantity || allocation.allocatedQuantity <= 0) {
        lineDebug.action = 'removed';

        debugInfo.removedLines.push(lineDebug);

        returnAuthRec.removeLine({
          sublistId: 'item',
          line: i,
          ignoreRecalc: true
        });

        continue;
      }

      returnAuthRec.selectLine({
        sublistId: 'item',
        line: i
      });

      returnAuthRec.setCurrentSublistValue({
        sublistId: 'item',
        fieldId: 'quantity',
        value: Number(allocation.allocatedQuantity)
      });

      returnAuthRec.commitLine({
        sublistId: 'item'
      });

      lineDebug.action = 'kept';
      lineDebug.finalQuantity = Number(allocation.allocatedQuantity);

      debugInfo.keptLines.push(lineDebug);

      hasValidLine = true;
    }

    if (!hasValidLine) {
      throw new Error(
        'No valid refunded item lines were found for Shopify order ' +
          rmaData.shopifyOrderName +
          '. Debug summary: salesOrderLineCount=' +
          debugInfo.salesOrderLineCount +
          ', returnAuthLineCountImmediatelyAfterTransform=' +
          debugInfo.returnAuthLineCountImmediatelyAfterTransform +
          ', matchedItemsCount=' +
          matchedItems.length +
          ', keptLinesCount=' +
          debugInfo.keptLines.length +
          ', removedLinesCount=' +
          debugInfo.removedLines.length +
          ', unallocatedMatchedQuantitiesCount=' +
          debugInfo.unallocatedMatchedQuantities.length
      );
    }

    if (debugInfo.unallocatedMatchedQuantities.length > 0) {
      throw new Error(
        'Could not allocate the full refunded quantity to return authorization lines for Shopify order ' +
          rmaData.shopifyOrderName +
          '. Debug summary: salesOrderLineCount=' +
          debugInfo.salesOrderLineCount +
          ', returnAuthLineCountImmediatelyAfterTransform=' +
          debugInfo.returnAuthLineCountImmediatelyAfterTransform +
          ', matchedItemsCount=' +
          matchedItems.length +
          ', keptLinesCount=' +
          debugInfo.keptLines.length +
          ', removedLinesCount=' +
          debugInfo.removedLines.length +
          ', unallocatedMatchedQuantitiesCount=' +
          debugInfo.unallocatedMatchedQuantities.length
      );
    }

    const returnAuthId = returnAuthRec.save();

    return {
      success: true,
      id: returnAuthId,
      externalId: rmaData.externalId,
      debug: debugInfo
    };
  } catch (error) {
    return {
      success: false,
      message: error.message,
      stack: error.stack,
      errorName: error.name,
      debug: debugInfo
    };
  }
}

execute();

const rmaData = input['mapMatchRefundedItemsToSalesOrderLines'][0];
const rma = input['netsuiteCreateReturnAuthorization'][0];
const accountId = input.system?.netsuiteAccountId || '{{NETSUITE_ACCOUNT_ID}}';
const rmaUrl = `https://${accountId}.app.netsuite.com/app/accounting/transactions/rtnauth.nl?id=${rma.id}`;

return {
  to: 'jjones@lionel.com, AMiller@lionel.com',
  subject: `NetSuite RMA created for Shopify order ${rmaData.shopifyOrderName}`,
  body: `A NetSuite RMA has been created for Shopify order ${rmaData.shopifyOrderName}.\n\nRMA ID: ${rma.id}\nRMA Link: ${rmaUrl}\nShopify Order ID: ${rmaData.shopifyOrderId}\nShopify Refund ID: ${rmaData.refundId}`,
  rmaUrl
};
